mapper.select:
select sum(total_amount)
from contract
where sign_date between #{reportStartTime} and #{reportEndTime}

select count(*)
from contract
where sign_date between #{reportStartTime} and #{reportEndTime}
  and contract_status = #{status}

SELECT c2.source as chartTitle, COUNT(*) as num FROM contract c1 LEFT JOIN customer_company c2 ON c1.company_id = c2.id WHERE sign_date BETWEEN #{startTime} AND #{endTime}
AND c1.contract_status = #{status}
GROUP BY c2.source ORDER BY num DESC

SELECT COUNT(*)
FROM contract
WHERE sign_date BETWEEN #{startTime} AND #{endTime}
